// Package each email for VendorIQ: sender, subject, plain text, SPF/DKIM result and attachments (base64).
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json;
  const attachments = [];
  for (const key of Object.keys(item.binary || {})) {
    const meta = item.binary[key];
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    attachments.push({ name: meta.fileName || key, mime: meta.mimeType, b64: buf.toString('base64') });
  }
  const headers = j.headers || {};
  out.push({ json: {
    gmail_id: j.id,
    from: (j.from && (j.from.text || (j.from.value && j.from.value[0] && j.from.value[0].address))) || '',
    subject: j.subject || '',
    text: j.text || '',
    message_id: j.messageId || j.id,
    auth: headers['authentication-results'] || '',
    attachments,
  }});
}
return out;

