// Package each email for VendorIQ: sender, subject, text, SPF/DKIM result and attachments (base64).
// Skips mail that is neither a vendor application (has attachments) nor a reply to one of our requests.
const own = ($env.SMTP_FROM_ADDRESS || '').toLowerCase();
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json;
  const fromText = (j.from && (j.from.text || (j.from.value && j.from.value[0] && j.from.value[0].address))) || '';
  const subject = j.subject || '';
  const attachments = [];
  for (const key of Object.keys(item.binary || {})) {
    const meta = item.binary[key];
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    attachments.push({ name: meta.fileName || key, mime: meta.mimeType, b64: buf.toString('base64') });
  }
  const isReply = /\[VEN-\d{4}-\d{5}\]/.test(subject);
  if (own && fromText.toLowerCase().includes(own)) continue;
  if (!attachments.length && !isReply) continue;
  const h = j.headers || {};
  const auth = h['authentication-results'] || (typeof h.get === 'function' ? h.get('authentication-results') : '') || '';
  out.push({ json: { from: fromText, subject, text: j.text || '', message_id: j.messageId || '', auth: String(auth), attachments } });
}
return out;
